// Inline Leaflet's JS + CSS into a TS module so the in-app map needs no CDN at runtime.
// Run after changing the leaflet version: `npm run vendor:leaflet`.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dist = path.join(root, 'node_modules', 'leaflet', 'dist');
const { version } = JSON.parse(fs.readFileSync(path.join(root, 'node_modules', 'leaflet', 'package.json'), 'utf8'));
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
// The app only draws circle markers, so the default marker/layer images are not needed.
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8').replace(/url\([^)]*\)/g, 'none');

const out = `/* eslint-disable */
// GENERATED by scripts/vendor-leaflet.mjs from leaflet@${version} — do not edit.
// Leaflet is (c) Vladimir Agafonkin and contributors, BSD-2-Clause licence.
export const LEAFLET_VERSION = ${JSON.stringify(version)};
export const LEAFLET_JS = ${JSON.stringify(js)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
`;
fs.writeFileSync(path.join(root, 'src', 'components', 'map', 'leafletAssets.ts'), out);
console.log(`Wrote leafletAssets.ts (leaflet ${version}, ${Math.round(out.length / 1024)} KB)`);
